#[inline(always)]
unsafe fn field_ptr<T>(base: *mut u8, offset: SizeT) -> *mut T {
    base.add(offset).cast::<T>()
}

#[inline(always)]
unsafe fn ptrace_copy_bytes(dst: *mut u8, src: *const u8, bytes: SizeT) {
    let mut offset = 0;
    while offset < bytes {
        dst.add(offset)
            .write_volatile(src.add(offset).read_volatile());
        offset += 1;
    }
}

