#[inline(always)]
fn syscall_make_kill_siginfo(sig: CInt, code: CInt, pid: CInt) -> SigInfo {
    SigInfo {
        si_signo: sig,
        si_errno: 0,
        si_code: code,
        padding: 0,
        sifields: crate::abi::SigInfoFields {
            kill: ManuallyDrop::new(SigInfoKill {
                si_pid: pid,
                si_uid: 0,
            }),
        },
    }
}

